
// Main pipeline: topic -> documentary script (Gemini) -> human-sounding
// narration with exact timing (msedge-tts) -> real video clips/photos per
// segment (Pexels/Unsplash) -> assembled synced video (ffmpeg) -> uploaded
// to the NEXTSCENE TV YouTube channel.
//
// This is the LONG-FORM pipeline (~60-90s, landscape 1920x1080).
//
// The thumbnail is generated by the working Python thumbnail compositor:
// Gemini + FLUX.1-schnell + Pillow.
//
// Required environment variables:
//   GEMINI_API_KEY
//   PEXELS_API_KEY
//   UNSPLASH_API_KEY            (optional fallback)
//   GOOGLE_CLIENT_ID
//   GOOGLE_CLIENT_SECRET
//   YOUTUBE_REFRESH_TOKEN
//   HF_TOKEN                    (for FLUX thumbnail generation)
//
// Run locally to test without uploading:
//   node scripts/generate-documentary.mjs --no-upload

import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { execFile } from "node:child_process";
import { promisify } from "node:util";

import { synthesizeNarration } from "./lib/tts.mjs";
import { fetchVisualForSegment, fetchFlag, writeAssetManifest } from "./lib/visuals.mjs";
import { pickMusicBed, findSfxClip } from "./lib/audio-library.mjs";
import {
  buildDocumentary,
  CARD_THEMES,
  extractThumbnail,
} from "./lib/ffmpeg-build.mjs";
import { generateScript, reviewScriptClaims, NEXTSCENE_BRAND_LINE } from "./lib/script-gen.mjs";
import { pickWithPriority } from "./lib/topic-history.mjs";
import {
  uploadToYouTube,
  getOrCreatePlaylist,
  addVideoToPlaylist,
  setThumbnail,
} from "./lib/youtube.mjs";
import { buildHashtags, buildTags } from "./lib/seo.mjs";

const execFileAsync = promisify(execFile);

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const NO_UPLOAD = process.argv.includes("--no-upload");

const TOPIC_HISTORY_PATH = path.join(
  __dirname,
  "..",
  "state",
  "topic-history-long.json"
);

// Sept 15 2026: "post this next" queue for the long-form pipeline — same
// mechanism and reasoning as PRIORITY_QUEUE_PATH in generate-short.mjs, see
// pickWithPriority in lib/topic-history.mjs. Separate file from the Shorts
// one so the two pipelines (separate workflows, separate schedules) never
// touch the same file.
const PRIORITY_QUEUE_PATH = path.join(
  __dirname,
  "..",
  "state",
  "priority-queue-long.json"
);

// Python thumbnail compositor.
const THUMBNAIL_COMPOSITOR = path.join(
  __dirname,
  "lib",
  "thumbnail_compositor.py"
);

// Sept 30 2026 strategy reset: long-form is now ONE 8-10 minute deep dive a
// week, expanding the Money & Power stories that performed best as Shorts.
// The old 91-topic 'Top 10' pool is retired (long-form averaged a handful
// of views per video).
const MONEY_DEEP_DIVES = [
  "How Luxembourg became the richest country on Earth",
  "How tiny island nations became billionaire playgrounds",
  "The richest tiny countries on Earth and how they did it",
  "Which countries have the most gold, and why they're hoarding it",
  "How Qatar went from pearl diving to one of the richest nations on Earth",
  "How Dubai built a global city in one lifetime",
  "How Saudi Arabia plans to survive after oil",
  "How Botswana turned diamonds into Africa's quiet success story",
  "How Kenya became the world leader in mobile money",
  "How Rwanda rebuilt its economy in one generation",
  "How Mauritius became Africa's richest country per person",
  "Why Nigeria's oil wealth never reached most Nigerians",
  "How South Korea went from poorer than Kenya to a tech giant",
  "How Singapore went from swamp to financial superpower",
  "How Norway turned oil into the world's biggest savings fund",
  "How Switzerland got rich by staying neutral",
  "How Venezuela went from richest in South America to collapse",
  "How the Gulf states are spending oil money to buy the future",
  "How China lifted hundreds of millions out of poverty",
  "Why the US dollar still rules the world, and who is trying to replace it",
];

const POWER_DEEP_DIVES = [
  "The chokepoints that control the world's oil and trade",
  "The global race for lithium, cobalt and the metals of the future",
];

const TOPIC_POOL = [...MONEY_DEEP_DIVES, ...POWER_DEEP_DIVES];

const SUBSCRIBE_LINE =
  "If you're finding this useful, hit subscribe — it really helps this channel grow.";

const SUBSCRIBE_VISUAL_QUERY =
  "smartphone social media scrolling";

const INTRO_WELCOME_LINE =
  "Welcome to NextScene TV — the future uncovered.";

// Sept 16 2026 (channel-upgrade brief): the outro now leads with the
// channel's one deterministic brand line (see NEXTSCENE_BRAND_LINE in
// lib/script-gen.mjs, shared with the Shorts pipeline) before the
// subscribe ask, instead of going straight to a plain "thanks for
// watching" — same reasoning as the Shorts pipeline's brand-close segment.
const OUTRO_LINE =
  `${NEXTSCENE_BRAND_LINE} Subscribe to NextScene for more.`;

const OUTRO_CARD_LINES = [
  NEXTSCENE_BRAND_LINE.toUpperCase(),
  "NEXTSCENE — THE FUTURE UNCOVERED",
];

const INTRO_BG_QUERY =
  "futuristic city skyline night aerial";

const OUTRO_BG_QUERY =
  "city skyline night lights aerial";

// Sept 16 2026 (channel-upgrade brief): long-form's 91-topic TOPIC_POOL
// predates the 5-pillar system and is almost entirely "Top 10 X" ranking
// topics, so rather than hand-tag all 91 (a lot of genuinely ambiguous
// judgment calls for a ranking-format topic), this infers a pillar from
// each topic's own keywords at pick time and passes it to generateScript()
// so Gemini writes it in that pillar's voice (see PILLAR_GUIDANCE in
// lib/script-gen.mjs). Defaults to World Power, the closest fit for a
// generic "Top 10 countries with the most/strongest/biggest X" ranking.
// This does NOT yet file long-form videos into per-pillar playlists —
// long-form still only has the one catch-all PLAYLIST_TITLE below; see the
// channel-upgrade plan for why that wasn't extended here yet (long-form is
// 500 views/30 days vs Shorts' 5,988, so the playlist work went to Shorts
// first, where the real analytics weight actually is).
function inferPillar(topic) {
  return POWER_DEEP_DIVES.includes(topic) ? "World Power" : "Money & Power";
}

const PLAYLIST_TITLE =
  "Deep Dives — NEXTSCENE TV";

const PLAYLIST_DESCRIPTION =
  "8-10 minute deep dives into how countries really got rich, and the money and power behind them — NEXTSCENE TV.";

/*
 * Generate exactly ONE custom thumbnail.
 *
 * Python compositor:
 * Gemini -> FLUX.1-schnell -> Pillow
 */
async function generateCustomThumbnail(title, runDir) {
  console.log(
    "[thumbnail] generating new Gemini + FLUX + Pillow thumbnail..."
  );

  const outputDir = path.join(
    runDir,
    "thumbnail-output"
  );

  await fs.mkdir(
    outputDir,
    { recursive: true }
  );

  try {
    await execFileAsync(
      "python3",
      [
        THUMBNAIL_COMPOSITOR,
        "--title",
        title,
        "--variations",
        "1",
        "--out-dir",
        outputDir,
      ],
      {
        cwd: path.join(__dirname, ".."),
        env: process.env,
        maxBuffer: 10 * 1024 * 1024,
      }
    );

    const generatedPath = path.join(
      outputDir,
      "thumbnail_01.jpg"
    );

    const finalThumbnailPath = path.join(
      runDir,
      "thumbnail.jpg"
    );

    await fs.access(
      generatedPath
    );

    await fs.copyFile(
      generatedPath,
      finalThumbnailPath
    );

    console.log(
      "[thumbnail] ready: " +
        finalThumbnailPath
    );

    return finalThumbnailPath;
  } catch (err) {
    console.warn(
      "[thumbnail] new compositor failed: " +
        err.message
    );

    return null;
  }
}

async function main() {
  const runDir = path.join(
    __dirname,
    "..",
    "tmp",
    "run_" + Date.now()
  );

  await fs.mkdir(
    runDir,
    { recursive: true }
  );

  const topic =
    await pickWithPriority(
      TOPIC_POOL,
      TOPIC_HISTORY_PATH,
      PRIORITY_QUEUE_PATH,
      "topic"
    );

  console.log(
    "[topic] " + topic
  );

  const pillar = inferPillar(topic);
  console.log(
    "[topic] pillar: " + pillar
  );

  console.log(
    "[script] generating with Gemini..."
  );

  const script =
    await generateScript(topic, { pillar, deep: true });

  console.log(
    "[script] title: " +
      script.title +
      " (" +
      script.segments.length +
      " segments)"
  );

  // Best-effort fact-check pass (see reviewScriptClaims in
  // lib/script-gen.mjs) — same reasoning as the Shorts pipeline: no human
  // review gate on scheduled runs, so this softens any claim the model
  // isn't confident is broadly well-established rather than blocking.
  console.log(
    "[fact-check] reviewing claims before narration..."
  );

  const claimTexts =
    script.segments
      .map((s) => s.text)
      .concat(
        script.commentary ? [script.commentary] : []
      );

  const { sentences: reviewedTexts } =
    await reviewScriptClaims(claimTexts, topic);

  script.segments.forEach((s, i) => {
    s.text = reviewedTexts[i] ?? s.text;
  });

  if (script.commentary) {
    script.commentary =
      reviewedTexts[script.segments.length] ?? script.commentary;
  }

  const midIndex = Math.max(
    1,
    Math.floor(
      script.segments.length / 2
    )
  );

  script.segments.splice(
    midIndex,
    0,
    {
      text: SUBSCRIBE_LINE,
      location: "",
      visualQuery:
        SUBSCRIBE_VISUAL_QUERY,
      isSubscribeCTA: true,
    }
  );

  const introCardLines = [
    script.title.toUpperCase(),
    "NEXTSCENE TV — THE FUTURE UNCOVERED",
  ];

  script.segments.unshift(
    {
      text:
        script.title + ".",
      location: "",
      visualQuery: "",
      isIntro: true,
    },
    {
      text:
        INTRO_WELCOME_LINE,
      location: "",
      visualQuery: "",
      isIntro: true,
    }
  );

  if (script.commentary) {
    const commentaryQuery =
      script.keywords &&
      script.keywords.length
        ? script.keywords[0] +
          " global analysis"
        : "world map global analysis data";

    script.segments.push({
      text: script.commentary,
      location: "",
      visualQuery:
        commentaryQuery,
      isCommentary: true,
    });
  }

  script.segments.push({
    text: OUTRO_LINE,
    location: "",
    visualQuery: "",
    isOutro: true,
  });

  const fullNarration =
    script.segments
      .map((s) => s.text)
      .join(" ");

  console.log(
    "[tts] synthesizing narration (en-KE-AsiliaNeural, Kenyan English, female)..."
  );

  const narration =
    await synthesizeNarration(
      fullNarration,
      runDir,
      "en-KE-AsiliaNeural"
    );

  const audioPath =
    narration.audioPath;

  const sentences =
    narration.sentences;

  if (
    sentences.length !==
    script.segments.length
  ) {
    console.warn(
      "[tts] warning: got " +
        sentences.length +
        " sentence boundaries but " +
        script.segments.length +
        " script segments — " +
        "TTS sentence splitting doesn't always match 1:1. " +
        "Falling back to even time distribution."
    );
  }

  console.log(
    "[visuals] fetching real clips/photos per segment..."
  );

  const segmentsForBuild = [];
  const assetManifest = []; // source/license record for every fetched asset — see lib/visuals.mjs writeAssetManifest

  let introBgVisual;
  let introDurationSec = 0;

  for (
    let i = 0;
    i < script.segments.length;
    i++
  ) {
    const lastSentence =
      sentences.length > 0
        ? sentences[sentences.length - 1]
        : null;

    const timing =
      sentences[i] || {
        durationSec:
          (
            (lastSentence?.startSec || 0) +
            (lastSentence?.durationSec || 60)
          ) /
          script.segments.length,
      };

    let visual;

    if (
      script.segments[i].isIntro
    ) {
      if (
        introBgVisual ===
        undefined
      ) {
        introBgVisual =
          await fetchVisualForSegment(
            {
              query:
                INTRO_BG_QUERY,
            },
            runDir,
            i
          ).catch(
            () => null
          );
      }

      visual = {
        type: "title-card",
        lines: introCardLines,
        fontsize: 58,
        bgVisual:
          introBgVisual,
      };

      introDurationSec +=
        timing.durationSec;

      console.log(
        "  segment " +
          i +
          ": intro card — \"" +
          script.segments[i]
            .text +
          "\" (" +
          timing.durationSec.toFixed(
            1
          ) +
          "s)" +
          (
            introBgVisual
              ? ""
              : " [no bg photo found, using flat card]"
          )
      );
    } else if (
      script.segments[i].isOutro
    ) {
      const bgVisual =
        await fetchVisualForSegment(
          {
            query:
              OUTRO_BG_QUERY,
          },
          runDir,
          i
        ).catch(
          () => null
        );

      visual = {
        type: "title-card",
        lines:
          OUTRO_CARD_LINES,
        bgVisual,
      };

      console.log(
        "  segment " +
          i +
          ": outro card (" +
          timing.durationSec.toFixed(
            1
          ) +
          "s)" +
          (
            bgVisual
              ? ""
              : " [no bg photo found, using flat card]"
          )
      );
    } else {
      visual =
        await fetchVisualForSegment(
          {
            query:
              script.segments[i]
                .visualQuery,
            location:
              script.segments[i]
                .location,
          },
          runDir,
          i
        ).catch(
          (err) => {
            console.warn(
              "[visuals] segment " +
                i +
                " (\"" +
                script.segments[i]
                  .visualQuery +
                "\") failed: " +
                err.message
            );

            return null;
          }
        );

      const matched =
        visual?.matchedTerm
          ? " matched \"" +
            visual.matchedTerm +
            "\""
          : "";

      console.log(
        "  segment " +
          i +
          ": " +
          (
            visual
              ? visual.type
              : "NO VISUAL FOUND"
          ) +
          matched +
          " — wanted \"" +
          script.segments[i]
            .visualQuery +
          "\" (" +
          timing.durationSec.toFixed(
            1
          ) +
          "s)"
      );

      if (
        visual &&
        script.segments[i]
          .countryCode
      ) {
        const flagPath =
          await fetchFlag(
            script.segments[i]
              .countryCode,
            runDir
          ).catch(
            () => null
          );

        if (flagPath) {
          visual.badge = {
            rank:
              script.segments[i]
                .rank ?? null,
            countryName:
              script.segments[i]
                .location || "",
            flagPath,
          };

          console.log(
            "    + badge: rank " +
              (
                visual.badge.rank ??
                "—"
              ) +
              ", flag " +
              script.segments[i]
                .countryCode
          );
        } else {
          console.warn(
            "    flag fetch failed for \"" +
              script.segments[i]
                .countryCode +
              "\" — no badge for this segment"
          );
        }
      }
    }

    const assetSource = visual?.source ? visual : visual?.bgVisual?.source ? visual.bgVisual : null;
    if (assetSource) {
      assetManifest.push({
        segment: i,
        type: assetSource.type,
        matchedTerm: assetSource.matchedTerm,
        source: assetSource.source,
        sourceId: assetSource.sourceId,
        pageUrl: assetSource.pageUrl,
        license: assetSource.license,
      });
    }

    segmentsForBuild.push({
      visual: visual,
      durationSec:
        timing.durationSec,
      text:
        script.segments[i]
          .text,
    });
  }

  const theme =
    CARD_THEMES[
      Math.floor(
        Math.random() *
          CARD_THEMES.length
      )
    ];

  console.log(
    "[theme] using \"" +
      theme.name +
      "\" card theme"
  );

  const outputPath =
    path.join(
      runDir,
      "final.mp4"
    );

  // music bed + a short transition SFX are both best-effort/non-fatal (see
  // lib/audio-library.mjs) — a video renders narration-only, exactly as
  // before, if neither is configured yet
  const musicBed = await pickMusicBed(runDir).catch(() => null);
  const sfxClip = await findSfxClip(runDir).catch(() => null);
  if (musicBed) console.log("[audio] music bed: " + path.basename(musicBed.path) + " (" + musicBed.source + ")");
  if (sfxClip) {
    console.log("[audio] transition sfx: " + sfxClip.source + " #" + sfxClip.sourceId);
    assetManifest.push({ role: "sfx", source: sfxClip.source, sourceId: sfxClip.sourceId, pageUrl: sfxClip.pageUrl, license: sfxClip.license, attribution: sfxClip.attribution });
  }
  if (musicBed) assetManifest.push({ role: "music", source: musicBed.source, sourceId: musicBed.sourceId, pageUrl: musicBed.pageUrl, license: musicBed.license, attribution: musicBed.attribution });

  console.log(
    "[ffmpeg] assembling synced video (with voiced intro/outro)..."
  );

  await buildDocumentary(
    segmentsForBuild,
    audioPath,
    path.join(
      runDir,
      "work"
    ),
    outputPath,
    null,
    {
      theme: theme,
      musicPath: musicBed?.path ?? null,
      sfxPath: sfxClip?.path ?? null,
    }
  );
  await writeAssetManifest(assetManifest, path.join(runDir, "asset-manifest.json"));

  console.log(
    "[done] video ready: " +
      outputPath
  );

  // ------------------------------------------------------------
  // THUMBNAIL
  // ------------------------------------------------------------

  // Generate exactly ONE thumbnail using:
  // Gemini + FLUX.1-schnell + Pillow.
  //
  // If the new compositor fails, extract a frame from the video
  // as a fallback so the YouTube upload can still have a thumbnail.

  const thumbnailPath =
    path.join(
      runDir,
      "thumbnail.jpg"
    );

  let thumbnailReady = false;

  const generatedThumbnail =
    await generateCustomThumbnail(
      script.title,
      runDir
    );

  if (generatedThumbnail) {
    thumbnailReady = true;

    console.log(
      "[thumbnail] custom NEXTSCENE TV thumbnail ready"
    );
  } else {
    try {
      const atSec =
        Math.max(
          0.3,
          Math.min(
            1.5,
            introDurationSec *
              0.5
          )
        );

      await extractThumbnail(
        outputPath,
        thumbnailPath,
        atSec
      );

      thumbnailReady = true;

      console.log(
        "[thumbnail] extracted frame at " +
          atSec.toFixed(2) +
          "s (AI thumbnail unavailable)"
      );
    } catch (err) {
      console.warn(
        "[thumbnail] extraction failed too " +
          "(upload will keep YouTube's auto-picked frame): " +
          err.message
      );
    }
  }

  // ------------------------------------------------------------
  // UPLOAD
  // ------------------------------------------------------------

  if (NO_UPLOAD) {
    console.log(
      "[upload] skipped (--no-upload)"
    );

    return;
  }

  console.log(
    "[upload] pushing to NEXTSCENE TV..."
  );

  const coveredPlaces = [
    ...new Set(
      script.segments
        .map(
          (s) => s.location
        )
        .filter(Boolean)
    ),
  ];

  const hashtags =
    buildHashtags(
      script.keywords,
      [
        "#geopolitics",
        "#top10",
        "#futurepredictions",
      ]
    );

  const tags = buildTags(
    script.keywords,
    coveredPlaces,
    [
      "top10",
      "geopolitics",
      "future predictions",
      "documentary",
    ]
  );

  const description = [
    script.title,
    "",
    script.commentary ||
      "Auto-narrated documentary breakdown for NEXTSCENE TV — the future uncovered.",
    coveredPlaces.length
      ? "Covering: " +
        coveredPlaces.join(", ") +
        "."
      : "",
    "",
    "Subscribe for more Top 10 rankings, power comparisons, and future predictions.",
    "Want quick daily facts instead? Check the \"NEXTSCENE Shorts\" playlist on this channel.",
    "",
    hashtags.join(" "),
  ]
    .filter(Boolean)
    .join("\n");

  const uploaded =
    await uploadToYouTube(
      outputPath,
      script.title,
      description,
      { tags: tags }
    );

  console.log(
    "[upload] done: https://youtube.com/watch?v=" +
      uploaded.id
  );

  // ------------------------------------------------------------
  // YOUTUBE THUMBNAIL
  // ------------------------------------------------------------

  // This is the existing YouTube thumbnail upload.
  // It now receives the new Gemini + FLUX + Pillow thumbnail.

  if (thumbnailReady) {
    try {
      await setThumbnail(
        uploaded.id,
        thumbnailPath
      );

      console.log(
        "[thumbnail] custom thumbnail set on YouTube"
      );
    } catch (err) {
      console.warn(
        "[thumbnail] upload failed " +
          "(video still uploaded fine, keeping YouTube's auto-picked frame): " +
          err.message
      );
    }
  }

  // ------------------------------------------------------------
  // PLAYLIST
  // ------------------------------------------------------------

  try {
    const playlistId =
      await getOrCreatePlaylist(
        PLAYLIST_TITLE,
        PLAYLIST_DESCRIPTION
      );

    await addVideoToPlaylist(
      playlistId,
      uploaded.id
    );

    console.log(
      "[playlist] added to \"" +
        PLAYLIST_TITLE +
        "\""
    );
  } catch (err) {
    console.warn(
      "[playlist] failed " +
        "(video still uploaded fine): " +
        err.message
    );
  }
}

main().catch(
  (err) => {
    console.error(
      "[fatal]",
      err
    );

    process.exit(1);
  }
);
